-- Hyprland Lua config - converted from i3 config by Adam French
-- https://wiki.hypr.land/Configuring/
-- Built from colors.lua + base.lua by build.sh (edit base.lua, not hyprland.lua)

------------------
---- MONITORS ----
------------------

hl.monitor({ output = "", mode = "preferred", position = "auto", scale = 1 })
-- Per-machine layout generated by nwg-displays
pcall(require, "monitors")

---------------------
---- MY PROGRAMS ----
---------------------

local terminal = "kitty"
local fileManager = "kitty -e ranger"
local menu = "wofi --show drun"

----------------
---- CURSOR ----
----------------

hl.env("XCURSOR_THEME", "Miku Cursor")
hl.env("XCURSOR_SIZE", "48")
hl.env("HYPRCURSOR_SIZE", "48")

-------------------
---- AUTOSTART ----
-------------------

hl.on("hyprland.start", function()
	hl.exec_cmd("dex -a")
	hl.exec_cmd("/usr/lib/polkit-gnome/polkit-gnome-authentication-agent-1")
	hl.exec_cmd("wl-paste --watch cliphist store")
	hl.exec_cmd("dunst")
	hl.exec_cmd("hypridle")
	hl.exec_cmd("hyprpaper")
	hl.exec_cmd("gammastep -m wayland -l 51.5074:-0.1278 -t 6500:3500")
	hl.exec_cmd("waterfox")
	hl.exec_cmd("waybar")
end)

